-- IPA SG official past questions: 2016 autumn morning, questions 1-10.
-- Questions/options are from the published IPA paper; answers checked against the official key.
-- Official question PDF: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf
-- Official answer key: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_ans.pdf
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28a-2016-q01','exam-sg','利用者認証・ICカード','standard','single_choice','【2016年度 平成28年秋期 午前 問1】ICカードとPINを用いた利用者認証における適切な運用はどれか。','[{"id":"a","text":"ICカードで利用者を識別できるので，全利用者に共通のPINを設定する。"},{"id":"b","text":"ICカード紛失時には，新しいカードを発行してPINを再設定した後で，紛失したカードを失効させる。"},{"id":"c","text":"PINにはICカードの表面に刻印してある数字情報を組み合わせて設定する。"},{"id":"d","text":"PINはICカードの配送に同封せず，別経路で利用者に知らせる。"}]','"d"','正解はエ。カードとPINを別経路で配布することで，カードと認証情報が同時に漏れるリスクを下げる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q02','exam-sg','リスク対応・リスク共有','standard','single_choice','【2016年度 平成28年秋期 午前 問2】リスクの顕在化に備えて地震保険に加入するという対応は，JIS Q 31000:2010に示されているリスク対応のうち，どれに分類されるか。','[{"id":"a","text":"ある機会を追求するために，そのリスクを取る又は増加させる。"},{"id":"b","text":"一つ以上の他者とそのリスクを共有する。"},{"id":"c","text":"リスク源を除去する。"},{"id":"d","text":"リスクを生じさせる活動を開始又は継続しないと決定して，リスクを回避する。"}]','"b"','正解はイ。保険加入は損失の一部を保険会社と分担するリスク共有（移転）に当たる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q03','exam-sg','インシデント対応・JPCERT/CC','standard','single_choice','【2016年度 平成28年秋期 午前 問3】JPCERT/CCの説明はどれか。','[{"id":"a","text":"工業標準化法に基づき，工業標準化全般の調査・審議を行う組織"},{"id":"b","text":"電子政府推奨暗号の安全性を評価・監視する暗号技術検討プロジェクト"},{"id":"c","text":"独立した組織として，国内のコンピュータセキュリティインシデントの報告受付，対応支援，分析や再発防止の助言を行う組織"},{"id":"d","text":"内閣官房に設置され，サイバー攻撃から日本を防衛する司令塔機能を担う組織"}]','"c"','正解はウ。JPCERT/CCはコンピュータセキュリティインシデントの報告受付や対応支援，情報提供などを行う組織である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q04','exam-sg','脆弱性情報・JVN','standard','single_choice','【2016年度 平成28年秋期 午前 問4】JVN（Japan Vulnerability Notes）はどれか。','[{"id":"a","text":"情報システムに存在する脆弱性の深刻度を評価する手法"},{"id":"b","text":"製品に存在する脆弱性に対して採番された識別子"},{"id":"c","text":"脆弱性対策情報などを提供するポータルサイト"},{"id":"d","text":"組織内の情報セキュリティ問題を専門に扱うインシデント対応チーム"}]','"c"','正解はウ。JVNは脆弱性情報や対策情報を提供するポータルサイトであり，識別子そのものや対応チームではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q05','exam-sg','可用性・冗長化','standard','single_choice','【2016年度 平成28年秋期 午前 問5】ファイルサーバについて，情報セキュリティにおける可用性を高めるための管理策として適切なものはどれか。','[{"id":"a","text":"ストレージを二重化し，耐障害性を向上させる。"},{"id":"b","text":"ディジタル証明書を利用し，利用者の本人確認を可能にする。"},{"id":"c","text":"ファイルを暗号化し，情報漏えいを防ぐ。"},{"id":"d","text":"フォルダにアクセス権を設定し，部外者の不正アクセスを防止する。"}]','"a"','正解はア。ストレージの二重化は機器故障による停止リスクを低減し，可用性を高める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q06','exam-sg','リスク評価・ベースラインアプローチ','standard','single_choice','【2016年度 平成28年秋期 午前 問6】情報セキュリティ対策を検討する手法の一つであるベースラインアプローチの特徴はどれか。','[{"id":"a","text":"基準とする望ましい対策と，組織の現状における対策とのギャップを分析する。"},{"id":"b","text":"現場担当者の経験や考え方によって検討結果が左右されやすい。"},{"id":"c","text":"情報資産ごとにリスクを分析する。"},{"id":"d","text":"複数のアプローチを併用し，分析作業の効率化や精度向上を図る。"}]','"a"','正解はア。ベースラインアプローチでは，基準となる対策水準と現状との差を把握して必要な対策を検討する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q07','exam-sg','ID管理・退職者アカウント','standard','single_choice','【2016年度 平成28年秋期 午前 問7】利用者IDの発行・削除は申請に基づいて行われているが，申請漏れや反映漏れがある。退職者の利用者IDの削除漏れを最も確実に発見できる資料Aと資料Bの組合せはどれか。','[{"id":"a","text":"資料A：組織の現在の所属者の名簿／資料B：退職に伴う利用者IDの削除申請書"},{"id":"b","text":"資料A：退職者の一覧／資料B：組織の現在の所属者の名簿"},{"id":"c","text":"資料A：利用者IDとその発行対象者の一覧／資料B：組織の現在の所属者の名簿"},{"id":"d","text":"資料A：利用者IDとその発行対象者の一覧／資料B：退職に伴う利用者IDの削除申請書"}]','"c"','正解はウ。実際に発行されているIDの一覧と現在の所属者名簿を突き合わせると，退職後も残るIDを検出できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q08','exam-sg','リスク評価','standard','single_choice','【2016年度 平成28年秋期 午前 問8】JIS Q 27000におけるリスク評価はどれか。','[{"id":"a","text":"対策を講じることによってリスクを修正するプロセス"},{"id":"b","text":"リスクが受容可能か否かを決定するため，リスク分析の結果をリスク基準と比較するプロセス"},{"id":"c","text":"リスクの特質を理解し，リスクレベルを決定するプロセス"},{"id":"d","text":"リスクの発見，認識及び記述を行うプロセス"}]','"b"','正解はイ。リスク評価は，リスク分析の結果をリスク基準と比較し，受容可能性や対応の必要性を判断する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q09','exam-sg','リスク対応・残留リスク','standard','single_choice','【2016年度 平成28年秋期 午前 問9】JIS Q 31000:2010における残留リスクの定義はどれか。','[{"id":"a","text":"監査手続を実施しても監査人が重要な不備を発見できないリスク"},{"id":"b","text":"業務の性質や本来有する特性から生じるリスク"},{"id":"c","text":"利益を生む可能性に内在する損失発生の可能性として存在するリスク"},{"id":"d","text":"リスク対応後に残るリスク"}]','"d"','正解はエ。残留リスクは，リスク対応を実施した後にも残るリスクであり，必要に応じて受容可否を判断する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q10','exam-sg','セキュリティ教育','standard','single_choice','【2016年度 平成28年秋期 午前 問10】情報セキュリティ意識向上のための教育の実施状況をJIS Q 27002に従ってレビューした。情報セキュリティ強化の観点から改善が必要な状況はどれか。','[{"id":"a","text":"従業員の受講記録を分析し，教育計画を見直している。"},{"id":"b","text":"従業員の職務内容や職制に応じた内容の教育を実施している。"},{"id":"c","text":"出張中で受講できなかった従業員を対象に追加の教育を実施している。"},{"id":"d","text":"正規従業員と同様の業務に従事する派遣従業員を除いて教育を実施している。"}]','"d"','正解はエ。情報セキュリティ教育は，業務に従事する派遣従業員などにも必要に応じて実施する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja');
